def leafReindex : {n : ℕ} → ((Fin n → ℕ) → (ℕ ↪ ℕ)) → NatTreeEmbedding (n + 1)
  | 0, f => (f Fin.elim0, fun _ => PUnit.unit)
  | _ + 1, f => (Function.Embedding.refl ℕ, fun i => leafReindex (fun p => f (Fin.cons i p)))

